//  Utilità
// ===========================================================================
const $ = (s, el = document) => el.querySelector(s);
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const norm = (s) => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const nf = new Intl.NumberFormat('it-IT', { maximumFractionDigits: 2 });
const fmtN = (n) => (n == null || n === '' ? '' : nf.format(Number(n)));
const pad = (n) => String(n).padStart(2, '0');
const dayKey = (d) => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
const fromKey = (k) => { const [y, m, d] = k.split('-').map(Number); return new Date(y, m - 1, d); };
const addDays = (d, n) => { const x = new Date(d); x.setDate(x.getDate() + n); return x; };
const toLocalInput = (d) => `${dayKey(d)}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
const fmtTime = (d) => `${pad(d.getHours())}:${pad(d.getMinutes())}`;
const fmtDay = (d) => d.toLocaleDateString('it-IT', { weekday: 'short', day: 'numeric', month: 'short' });
const fmtDate = (s) => (s ? new Date(s + (s.length === 10 ? 'T00:00' : '')).toLocaleDateString('it-IT', { day: 'numeric', month: 'short', year: 'numeric' }) : '');
const DEMO_PREVIEW = !!window.LABAPP_PREVIEW;
const isIOS = /iPad|iPhone|iPod/.test(navigator.userAgent) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
const isStandalone = () => matchMedia('(display-mode: standalone)').matches || navigator.standalone === true;

function ago(iso) {
  if (!iso) return '';
  const s = (Date.now() - new Date(iso)) / 1000;
  if (s < 90) return 'adesso';
  if (s < 3600) return `${Math.round(s / 60)} min fa`;
  if (s < 86400) return `${Math.round(s / 3600)} h fa`;
  if (s < 172800) return 'ieri';
  const d = Math.round(s / 86400);
  if (d < 60) return `${d} giorni fa`;
  if (d < 365) return `${Math.round(d / 30.4)} mesi fa`;
  return d < 730 ? 'più di un anno fa' : `${Math.floor(d / 365)} anni fa`;
}

function expiryInfo(expiry) {
  if (!expiry) return null;
  const days = Math.round((fromKey(expiry) - fromKey(dayKey(new Date()))) / 86400e3);
  if (days < 0) return { cls: 'danger', text: 'Scaduto', days };
  if (days === 0) return { cls: 'danger', text: 'Scade oggi', days };
  if (days <= 30) return { cls: 'warn', text: `Scade tra ${days} g`, days };
  return null;
}

