// dopo il salvataggio si torna da dove si era partiti: il Registro o la scheda dello strumento (giro 23), altrimenti l'elenco dell'amministrazione
function instrumentForm(inst, after = null) {
  const v = inst || { active: true };
  openSheet(inst ? 'Modifica strumento' : 'Nuovo strumento', `<form id="f" autocomplete="off">
    <label class="field"><span>Nome</span><input name="name" required maxlength="80" value="${esc(v.name)}" placeholder="es. Cappa a flusso laminare 2"></label>
    <label class="field"><span>Tipo</span><input name="kind" list="kinds" maxlength="40" value="${esc(v.kind)}" placeholder="cappa, microscopio…"></label>
    <label class="field"><span>Dove si trova</span><input name="location" maxlength="80" value="${esc(v.location)}"></label>
    <label class="field"><span>Ripiani (solo fitotroni e camere di crescita)</span><input name="shelves" type="number" inputmode="numeric" min="1" max="40" value="${esc(v.shelves)}" placeholder="lascia vuoto per gli altri strumenti">
      <span class="hint">Con i ripiani si prenota a giorni, un ripiano per esperimento</span></label>
    <div class="field"><span>Foto</span><div class="inst-photo-edit"><span id="ipv">${instPic(v)}</span>
      <div class="ipe-btns"><label class="btn small file-btn" style="position:relative;overflow:hidden">${icon('camera')}${instPhoto(v) ? 'Cambia' : 'Scatta o scegli'}<input type="file" id="ipf" accept="image/*" style="position:absolute;inset:0;opacity:0"></label>
        <button type="button" class="btn small ghost" id="ipx"${instPhoto(v) ? '' : ' hidden'}>Togli</button></div></div>
      <span class="hint">Si vede nei riquadri di Prenota. Senza foto c'è l'icona del tipo.</span></div>
    <label class="field"><span>Regole o note per chi prenota</span><textarea name="notes" maxlength="300">${esc(v.notes)}</textarea></label>
    <label class="field" style="flex-direction:row;align-items:center;gap:10px"><input type="checkbox" name="active" ${v.active ? 'checked' : ''} style="width:22px;min-height:22px"> <span style="color:var(--text)">Prenotabile</span></label>
    <p class="hint" style="margin-top:-6px">Se non si prenota resta comunque nel registro degli strumenti, con manutenzioni e colonne.</p>
    <datalist id="kinds">${['cappa biologica', 'cappa chimica', 'termociclatore', 'real-time PCR', 'sequenziatore Nanopore', 'lettore di piastre', 'centrifuga', 'centrifuga refrigerata', 'termomixer', 'bagnetto termostatico', 'omogeneizzatore', 'pHmetro', 'microscopio', 'incubatore', 'fitotrone', 'camera di crescita', 'LC-MS', 'HPLC', 'GC-MS', 'autoclave'].map((k) => `<option value="${k}">`).join('')}</datalist>
    <p class="err" id="err"></p>
    <button class="btn primary block" type="submit">Salva</button>
    ${inst ? `<button type="button" class="btn danger block" style="margin-top:10px" id="del">${icon('trash')}Elimina strumento</button>` : ''}</form>`, (sh) => {
    let photo = instPhoto(v);
    const showPhoto = () => { $('#ipv', sh).innerHTML = instPic({ ...v, kind: sh.querySelector('[name=kind]').value || v.kind, photo }); $('#ipx', sh).hidden = !photo; };
    $('#ipf', sh).onchange = async (e) => {
      const file = e.target.files[0]; e.target.value = '';
      if (!file) return;
      try { photo = await instThumb(file); showPhoto(); } catch { toast('Foto non leggibile'); }
    };
    $('#ipx', sh).onclick = () => { photo = null; showPhoto(); };
    $('#f', sh).onsubmit = (e) => {
      e.preventDefault();
      const d = formData(e.target);
      const sh0 = parseInt(d.shelves, 10);
      const payload = { name: d.name.trim(), kind: strOrNull(d.kind), location: strOrNull(d.location), notes: strOrNull(d.notes), active: !!d.active, shelves: sh0 >= 1 && sh0 <= 40 ? sh0 : null, photo };
      if (inst) payload.id = inst.id;
      busy(e.submitter, async () => {
        try { const row = await S.api.saveInstrument(payload); await loadData(true); toast('Salvato'); if (after) after(row); else adminInstruments(); } catch (x) { $('#err', sh).textContent = x.message; }
      });
    };
    const del = $('#del', sh);
    if (del) del.onclick = () => confirmSheet('Eliminare lo strumento?', 'Verranno cancellate anche tutte le sue prenotazioni. Per tenerle, togli la spunta "Prenotabile".', 'Elimina', true, async () => {
      try { await S.api.deleteInstrument(inst.id); await loadData(true); toast('Eliminato'); } catch (x) { toast(x.message); }
    });
  });
}

function exportCsv() {
  const cols = [['name', 'Nome'], ['category', 'Categoria'], ['quantity', 'Quantità'], ['unit', 'Unità'], ['min_quantity', 'Avviso a'], ['location', 'Posizione'],
    ['expiry', 'Scadenza'], ['lot', 'Lotto'], ['supplier', 'Fornitore'], ['catalog_no', 'Codice'], ['status', 'Stato'], ['notes', 'Note']];
  const cell = (v) => { const s = v == null ? '' : String(v); return /[";\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s; };
  const val = (it, k) => (k === 'category' ? catOf(it.category).short : k === 'status' ? { ok: 'ok', da_ordinare: 'da ordinare', ordinato: 'ordinato' }[it.status]
    : (k === 'quantity' || k === 'min_quantity') && it[k] != null ? String(it[k]).replace('.', ',') : it[k]);
  const csv = '﻿' + [cols.map((c) => c[1]).join(';'), ...S.items.map((it) => cols.map(([k]) => cell(val(it, k))).join(';'))].join('\r\n');
  saveBlob(new Blob([csv], { type: 'text/csv;charset=utf-8' }), `inventario-${dayKey(new Date())}.csv`);
}

function parseCsv(text) {
  text = text.replace(/^﻿/, '');
  const first = text.split(/\r?\n/, 1)[0];
  const delim = (first.match(/;/g) || []).length >= (first.match(/,/g) || []).length ? ';' : ',';
  const rows = [];
  let row = [], cell = '', q = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (q) {
      if (c === '"') { if (text[i + 1] === '"') { cell += '"'; i++; } else q = false; } else cell += c;
    } else if (c === '"') q = true;
    else if (c === delim) { row.push(cell); cell = ''; }
    else if (c === '\n' || c === '\r') {
      if (c === '\r' && text[i + 1] === '\n') i++;
      row.push(cell); cell = '';
      if (row.some((x) => x.trim() !== '')) rows.push(row);
      row = [];
    } else cell += c;
  }
  row.push(cell);
  if (row.some((x) => x.trim() !== '')) rows.push(row);
  return rows;
}

function csvToItems(text) {
  const rows = parseCsv(text);
  if (rows.length < 2) throw new Error('Il file non contiene righe');
  const head = rows[0].map((h) => norm(h).replace(/[^a-z ]/g, '').trim());
  const col = (...names) => head.findIndex((h) => names.includes(h));
  const ix = {
    name: col('nome', 'prodotto', 'articolo', 'name'), category: col('categoria', 'category'), quantity: col('quantita', 'quantity', 'qta'),
    unit: col('unita', 'unit', 'um'), min: col('avviso a', 'soglia', 'scorta minima', 'min'), location: col('posizione', 'dove', 'armadio', 'location'),
    expiry: col('scadenza', 'expiry'), lot: col('lotto', 'lot'), supplier: col('fornitore', 'marca', 'azienda', 'supplier'),
    code: col('codice', 'codice catalogo', 'codice prodotto', 'catalog'), status: col('stato', 'status'), notes: col('note', 'notes'),
  };
  if (ix.name < 0) throw new Error('Manca la colonna "Nome"');
  const catFor = (v) => {
    const n = norm(v).trim();
    if (!n || n === 'comune' || n === 'uso comune') return 'consumabili';
    const c = CATS.find((x) => x.id === n || norm(x.short) === n || norm(x.label) === n) || CATS.find((x) => norm(x.label).startsWith(n) || n.startsWith(norm(x.short)));
    return c ? c.id : 'consumabili';
  };
  const dateFor = (v) => {
    const t = String(v || '').trim();
    let m = t.match(/^(\d{4})-(\d{2})-(\d{2})/); if (m) return `${m[1]}-${m[2]}-${m[3]}`;
    m = t.match(/^(\d{1,2})[/.-](\d{1,2})[/.-](\d{2,4})$/);
    if (m) { const y = m[3].length === 2 ? `20${m[3]}` : m[3]; return `${y}-${pad(m[2])}-${pad(m[1])}`; }
    return null;
  };
  const statusFor = (v) => ({ 'da ordinare': 'da_ordinare', da_ordinare: 'da_ordinare', ordinato: 'ordinato' }[norm(v).trim()] || 'ok');
  const get = (r, i) => (i >= 0 ? String(r[i] ?? '').trim() : '');
  return rows.slice(1).map((r) => ({
    name: get(r, ix.name), category: catFor(get(r, ix.category)), quantity: numOrNull(get(r, ix.quantity)), unit: get(r, ix.unit) || 'pz',
    min_quantity: numOrNull(get(r, ix.min)), location: strOrNull(get(r, ix.location)), expiry: dateFor(get(r, ix.expiry)),
    lot: strOrNull(get(r, ix.lot)), supplier: strOrNull(get(r, ix.supplier)), catalog_no: strOrNull(get(r, ix.code)),
    status: statusFor(get(r, ix.status)), notes: strOrNull(get(r, ix.notes)),
  })).filter((it) => it.name && (it.quantity == null || !isNaN(it.quantity)) && (it.min_quantity == null || !isNaN(it.min_quantity)));
}

function importCsv() {
  openSheet('Importa articoli', `<p style="margin-top:0">Scegli un file CSV con almeno la colonna <b>Nome</b>. Le altre colonne riconosciute sono Categoria, Quantità, Unità, Avviso a, Posizione, Scadenza, Lotto, Fornitore, Codice, Note (come nel file esportato dall'app).</p>
    <label class="btn block" style="position:relative;overflow:hidden">${icon('upload')}Scegli il file
      <input type="file" id="csv" accept=".csv,text/csv,text/plain" style="position:absolute;inset:0;opacity:0"></label>
    <div id="prev"></div><p class="err" id="err"></p>`, (sh) => {
    $('#csv', sh).onchange = async (e) => {
      const file = e.target.files[0];
      if (!file) return;
      const err = $('#err', sh), prev = $('#prev', sh);
      err.textContent = '';
      let items;
      try { items = csvToItems(await file.text()); } catch (x) { err.textContent = x.message; return; }
      if (!items.length) { err.textContent = 'Nessun articolo valido nel file'; return; }
      const byCat = CATS.map((c) => [c.short, items.filter((i) => i.category === c.id).length]).filter(([, n]) => n);
      prev.innerHTML = `<div class="card" style="padding:14px;margin-top:14px"><b>${items.length} articoli pronti</b>
        <div style="color:var(--muted);font-size:14px;margin-top:4px">${byCat.map(([l, n]) => `${esc(l)} ${n}`).join(' · ')}</div>
        ${S.items.length ? `<div class="banner warn" style="margin-top:10px">${icon('alert')}<div>Vengono aggiunti ai ${S.items.length} già presenti, senza sostituirli.</div></div>` : ''}</div>
        <button type="button" class="btn primary block" id="go" style="margin-top:12px">${icon('upload')}Importa ${items.length} articoli</button>`;
      const go = $('#go', sh);
      go.onclick = () => busy(go, async () => {
        try {
          for (let i = 0; i < items.length; i += 200) {
            await S.api.importItems(items.slice(i, i + 200));
            go.textContent = `Importati ${Math.min(i + 200, items.length)} di ${items.length}…`;
          }
          closeSheet(); await loadData(true); toast(`${items.length} articoli importati`);
        } catch (x) { err.textContent = x.message; }
      });
    };
  });
}

async function logout() {
  try {
    if ('serviceWorker' in navigator) {
      const reg = await navigator.serviceWorker.getRegistration();
      const sub = await reg?.pushManager?.getSubscription();
      if (sub) { await S.api.deletePushSubscription(sub.endpoint).catch(() => {}); await sub.unsubscribe().catch(() => {}); }
    }
  } catch { /* nessuna iscrizione */ }
  await S.api.signOut();
  try { for (const k of await caches.keys()) if (k.startsWith('labapp-foto')) await caches.delete(k); } catch { /* niente cache */ }
  Object.assign(S, { uid: null, me: null, items: [], profiles: [], instruments: [], bookings: [], authMode: 'login' });
  render();
}

// ===========================================================================
