    const mm = res.products.length ? res.products[0].fmm + res.products[0].rmm : 0;
    const why = res.fOnly && res.rOnly ? `Siti di ${g.f.name} e ${g.r.name} presenti, ma non orientati per un prodotto.` : res.fOnly ? `Sito di ${g.r.name} assente.` : res.rOnly ? `Sito di ${g.f.name} assente.` : `Siti di ${g.f.name} e ${g.r.name} assenti.`;
