    return `<button type="button" class="card pair-card" data-act="pair-open" data-id="${x.id}"><div class="pr-top"><b>${esc(pairName(x))}</b>${x.locus ? `<span class="badge muted">${esc(x.locus)}</span>` : ''}${bad ? `<span class="pc-warn" title="Da controllare">${icon('alert')}</span>` : ''}${icon('chev', 'chev')}</div>
      <span class="pair-line">Annealing <b>${ta != null ? `${fmtN(ta)} °C` : '–'}</b> con ${esc(pol.sn)}${size ? ` · ${x.size_bp ? '' : '~'}${size} bp` : ''}${hits.length ? ` · ${nOf(hits.length, 'ceppo', 'ceppi')}` : ''}</span></button>`;
