// Rimanda: chi rimanda sceglie il giorno. Giro 52: dallo stesso foglio si passa la cosa a un collega
//   deleg: { cur: uid di chi la fa ora, pick: (uid) => ... }
function snoozeSheet(title, onPick, deleg = null) {
  const t = fromKey(todayKey());
  const mon = addDays(t, ((8 - t.getDay()) % 7) || 7);
  const opts = [[dayKey(addDays(t, 1)), 'Domani'], [dayKey(addDays(t, 3)), 'Fra 3 giorni'], [dayKey(mon), 'Lunedì prossimo'], [dayKey(addDays(t, 7)), 'Fra una settimana'], [dayKey(addDays(t, 30)), 'Fra un mese']];
  openSheet(`Rimanda: ${title}`, `<div class="seg" style="margin-bottom:12px">${opts.map(([k, l]) => `<button type="button" class="chip" data-k="${k}">${l}</button>`).join('')}</div>
    <form id="f"><label class="field"><span>Oppure scegli il giorno</span><input name="day" type="date" min="${dayKey(addDays(t, 1))}"></label>
    <button class="btn primary block" type="submit">Rimanda</button></form>
    ${deleg ? `<div class="section-title">${icon('user')}Oppure la fa un collega</div><div class="seg wrap deleg">${S.profiles.filter((p) => p.role !== 'pending' && p.id !== deleg.cur)
      .sort((a, b) => (b.id === S.uid) - (a.id === S.uid) || (a.full_name || '').localeCompare(b.full_name || '', 'it'))
      .map((p) => `<button type="button" class="chip" data-to="${p.id}">${p.id === S.uid ? 'Io' : esc(p.full_name || p.email)}</button>`).join('')}</div>
      <p class="hint">La trova nelle sue cose da fare, in Personali.</p>` : ''}`, (sh) => {
    const go = (k) => { closeSheet(); onPick(k); };
    sh.querySelectorAll('[data-to]').forEach((b) => (b.onclick = () => { closeSheet(); deleg.pick(b.dataset.to); }));
    sh.querySelectorAll('[data-k]').forEach((b) => (b.onclick = () => go(b.dataset.k)));
    $('#f', sh).onsubmit = (e) => { e.preventDefault(); const k = e.target.elements.day.value; if (k) go(k); };
  });
}
function snoozeTask(id) {
  const t = S.tasks.find((x) => x.id === id); if (!t) return;
  snoozeSheet(t.title, async (k) => {
    try { replaceTask(await S.api.saveTask({ ...t, due_on: k })); render(); toast(`Rimandato a ${fmtDay(fromKey(k))}`); } catch (e) { toast(e.message); }
  }, { cur: t.assigned_to, pick: async (uid) => {
    try { replaceTask(await S.api.saveTask({ ...t, assigned_to: uid })); render(); toast(uid === S.uid ? 'Ora tocca a te' : `Ora tocca a ${firstName(uid)}`); } catch (e) { toast(e.message); }
  } });
}
function snoozeStrain(id) {
  const st = S.strains.find((x) => x.id === id); if (!st) return;
  snoozeSheet(`ripicca di ${strainTitle(st)}`, async (k) => {
    try { replaceStrain(await S.api.saveStrain({ ...st, snooze_until: k })); render(); toast(`Ripicca rimandata a ${fmtDay(fromKey(k))}`); } catch (e) { toast(e.message); }
  });
}
function snoozeStock(id) {
  const x = S.stocks.find((y) => y.id === id); if (!x) return;
  const ref = strainOf(x)?.keeper_id || null;
  snoozeSheet(`${stockKind(x.kind).label.toLowerCase()} di ${strainTitle(strainOf(x))}`, async (k) => {
    try { replaceStock(await S.api.saveStock({ ...x, snooze_until: k })); render(); toast(`Rimandate a ${fmtDay(fromKey(k))}`); } catch (e) { toast(e.message); }
  }, { cur: stockKeeper(x), pick: async (uid) => {
    // le rifà il collega scelto ("Chi le rifà" della conservazione); se è il referente del ceppo torna al referente
    try { replaceStock(await S.api.saveStock({ ...x, keeper_id: uid === ref ? null : uid })); render(); toast(uid === S.uid ? 'Le rifai tu' : `Le rifà ${firstName(uid)}`); } catch (e) { toast(e.message); }
  } });
}

function taskCard(t) {
  const due = t.done ? null : dueLabel(t);
  const last = t.last_done_at ? `fatto da ${nameOf(t.last_done_by)} ${ago(t.last_done_at)}` : '';
  const meta = [t.instrument_id && S.instruments.find((i) => i.id === t.instrument_id)?.name, repeatLabel(t.repeat_days), t.location, last].filter(Boolean).join(' · ');
  const tags = [];
  if (due) tags.push(`<span class="badge ${due.cls}">${icon('clock')}${esc(due.text)}</span>`);
  if (t.assigned_to) tags.push(`<span class="badge info">${icon('user')}${t.assigned_to === S.uid ? 'tocca a te' : `per ${esc(person(t.assigned_to)?.full_name || 'qualcuno')}`}</span>`);
  if (t.done) tags.push(`<span class="badge ok">${icon('check')}fatto</span>`);
  return `<div class="item task" data-act="open-task" data-id="${t.id}" role="button" tabindex="0">
    <div class="body"><div class="name">${esc(t.title)}</div><div class="meta">${esc(meta)}</div><div class="tags">${tags.join('')}</div></div>
    ${t.done ? '' : `<div class="task-acts"><button type="button" class="done-btn" data-act="task-done" data-id="${t.id}" aria-label="Segna fatto: ${esc(t.title)}">${icon('check')}<span>Fatto</span></button><button type="button" class="later-btn" data-act="task-snooze" data-id="${t.id}" aria-label="Rimanda o passa a un collega: ${esc(t.title)}">${icon('clock')}</button></div>`}</div>`;
}

// giro 52: Da fare in due parti. Laboratorio: compiti comuni, strumenti, rifiuti, problemi e la micoteca senza referente.
// Personali: le cose di ognuno (conservazioni e ripicche dei propri ceppi, compiti che toccano a lui, campioni freschi),
// con un menu per vedere quelle di un collega
function tasksList() { return S.todoTab === 'mie' ? todoPersonal() : todoLab(); }
const todoSec = (title, ic, html, n) => (n ? `<div class="section-title">${icon(ic)}${title} <span class="count">${n}</span></div>${html}` : '');
const todoStrainRow = (st) => `<div class="item strain" data-act="strain-open" data-id="${st.id}" role="button" tabindex="0">
    <div class="cat-ic">${icon('petri')}</div><div class="body"><div class="name">Ripicca di ${st.code ? `<span class="mono">${esc(st.code)}</span> ` : ''}<i>${esc(st.species || '')}</i></div>
      <div class="meta">${esc([keeperLabel(st) && `ref. ${keeperLabel(st)}`, st.medium].filter(Boolean).join(' · '))}</div><div class="tags">${strainBadges(st)}</div></div>
    <div class="task-acts"><button type="button" class="done-btn" data-act="strain-sub" data-id="${st.id}" aria-label="Ripicca fatta">${icon('check')}<span>Fatta</span></button><button type="button" class="later-btn" data-act="strain-snooze" data-id="${st.id}" aria-label="Rimanda la ripicca">${icon('clock')}</button></div></div>`;
const todoStockRow = (x) => stockCard(x).replace(/<button type="button" class="act-btn" data-act="stock-renew" data-id="([^"]+)">Rifatte<\/button>/, '<div class="task-acts"><button type="button" class="done-btn" data-act="stock-renew" data-id="$1" aria-label="Rifatte oggi">' + icon('check') + '<span>Rifatte</span></button><button type="button" class="later-btn" data-act="stock-snooze" data-id="$1" aria-label="Rimanda o passa a un collega">' + icon('clock') + '</button></div>');
const todoRow = ({ k, x }) => `<div class="item todo-row" data-act="todo-open" data-k="${k}" data-id="${x.id}" role="button" tabindex="0"><div class="cat-ic">${icon(k === 'strain' ? 'petri' : k === 'proto' ? 'file' : k === 'sample' ? 'leaf' : 'flask')}</div>
    <div class="body"><div class="name">${esc(k === 'strain' ? strainTitle(x) : x.title || x.name)}</div><div class="meta">${{ strain: 'Micoteca', proto: 'Protocolli', sample: 'Campioni', item: 'Inventario' }[k]}, aggiunto al volo dal diario</div><div class="tags">${todoBadge(x)}</div></div>${icon('chev', 'chev')}</div>`;
const freshRows = (fresh) => `<div class="list">${fresh.map((it) => `<div class="item sample" data-act="open-item" data-id="${it.id}" data-c="campioni" role="button" tabindex="0"><div class="cat-ic">${sampleIcon(it.sample_type)}</div>
      <div class="body"><div class="name">${esc(it.name)}</div><div class="meta">liofilizza, congela o butta</div><div class="tags">${stateBadge(it)}${it.location ? `<span class="badge muted">${esc(it.location)}</span>` : ''}</div></div>${icon('chev', 'chev')}</div>`).join('')}</div>`;
function labTodoCount() {
  const open = openTasks().filter((t) => daysBetween(todayKey(), t.due_on) <= 7);
  return open.length + commonStocks().length + commonStrains().length;
}
function todoLab() {
  const today = todayKey();
  const open = openTasks().sort((a, b) => a.due_on.localeCompare(b.due_on) || a.title.localeCompare(b.title, 'it'));
  const soon = (t) => daysBetween(today, t.due_on) <= 7;
  const lab = open.filter((t) => !t.instrument_id && soon(t));
  const inst = open.filter((t) => t.instrument_id && soon(t));
  const later = open.filter((t) => !soon(t));
  const mico = [...commonStocks().map(todoStockRow), ...commonStrains().map(todoStrainRow)];
  const done = S.tasks.filter((t) => t.done).sort((a, b) => (b.last_done_at || '').localeCompare(a.last_done_at || '')).slice(0, 10);
  if (!open.length && !mico.length && !done.length) {
    return `<div class="empty">${icon('checklist')}<b>Nessun compito</b>Aggiungi le cose da fare in laboratorio, anche quelle che si ripetono come autoclave, puntali o acqua distillata. Le cose dei tuoi ceppi e dei tuoi campioni sono in Personali.</div>` + wasteSection() + problemsSection();
  }
  const late = open.filter((t) => t.due_on < today).length;
  const clear = !late && !open.some((t) => t.due_on === today) ? `<div class="banner ok-banner" style="margin-top:12px">${icon('checkCircle')}<div>Per oggi in laboratorio è tutto fatto.</div></div>` : '';
  return clear
    + todoSec('Compiti', 'checklist', `<div class="list">${lab.map(taskCard).join('')}</div>`, lab.length)
    + todoSec('Strumenti', 'tool', `<div class="list">${inst.map(taskCard).join('')}</div>`, inst.length)
    + todoSec('Micoteca, senza referente', 'petri', `<div class="list">${mico.join('')}</div>`, mico.length)
    + wasteSection() + problemsSection()
    + todoSec('Più avanti', 'calendar', `<div class="list">${later.map(taskCard).join('')}</div>`, later.length)
    + todoSec('Fatti di recente', 'checkCircle', `<div class="list">${done.map(taskCard).join('')}</div>`, done.length);
}
function todoPersonal() {
  const people = todoPeople(), me = `id:${S.uid}`;
  const who = S.todoWho && people.some(([k]) => k === S.todoWho) ? S.todoWho : me;
  const mine = who === me, name = mine ? '' : ownerLabel(who).split(' ')[0];
  const t = todoOf(who);
  const menu = people.length > 1 ? `<div class="mico-filters todo-who"><label class="mf-sel${mine ? '' : ' on'}">${icon('user')}<select data-todo-who aria-label="Di chi">${people.map(([k, n]) => `<option value="${esc(k)}"${k === who ? ' selected' : ''}>${esc(k === me ? 'Le mie' : ownerLabel(k))}${n ? ` (${n})` : ''}</option>`).join('')}</select>${icon('chev', 'chev')}</label></div>` : '';
  if (!t.n) return `${menu}<div class="empty">${icon('checkCircle')}<b>${mine ? 'Niente di tuo da fare' : `Niente da fare per ${esc(name)}`}</b>${mine ? 'Qui compaiono le conservazioni e le ripicche dei tuoi ceppi, i compiti che toccano a te e i campioni freschi da lavorare.' : ''}</div>`;
  const mico = [...t.stocks.map(todoStockRow), ...t.strains.map(todoStrainRow)];
  return menu
    + todoSec('Da completare', 'alert', `<div class="list">${t.todos.map(todoRow).join('')}</div>`, t.todos.length)
    + todoSec(mine ? 'Toccano a te' : `Toccano a ${esc(name)}`, 'checklist', `<div class="list">${t.tasks.map(taskCard).join('')}</div>`, t.tasks.length)
    + todoSec('Micoteca e colture', 'petri', `<div class="list">${mico.join('')}</div>`, mico.length)
    + todoSec('Campioni freschi da lavorare', 'leaf', freshRows(t.fresh), t.fresh.length);
}

// taniche piene da far ritirare, e il collegamento a tutte le taniche
function wasteSection() {
  const full = fullWaste(), act = activeWaste().length;
  const link = `<button type="button" class="link-btn" data-act="cat" data-cat="rifiuti" data-from="dafare">Tutte le taniche${icon('chev')}</button>`;
  const body = full.length ? wastePickupBlock(true).replace(/<button type="button" class="btn ghost block small" data-act="waste-view">Vai ai rifiuti<\/button>/, '')
    : `<div class="card quiet">${act ? `${n2(act, 'tanica in uso', 'taniche in uso')}, nessuna piena.` : 'Nessuna tanica registrata.'}</div>`;
  return `<div class="section-title">${icon('drum')}Rifiuti ${full.length ? `<span class="count">${full.length}</span>` : ''}${link}</div>${body}`;
}

// problemi aperti (non gli incidenti), e il collegamento alla sezione completa con il registro
function problemsSection() {
  const order = { alta: 0, normale: 1, bassa: 2 };
  const open = openIssues().filter((i) => !isIncident(i)).sort((a, b) => order[a.urgency] - order[b.urgency] || b.created_at.localeCompare(a.created_at));
  const inc = openIssues().filter(isIncident).length;
  const link = `<button type="button" class="link-btn" data-act="cat" data-cat="problemi" data-from="dafare">${inc ? `Tutti, ${n2(inc, 'incidente da verificare', 'incidenti da verificare')}` : 'Tutti e registro incidenti'}${icon('chev')}</button>`;
  const body = open.length ? `<div class="list">${open.slice(0, 5).map(issueCard).join('')}</div>${open.length > 5 ? `<button type="button" class="btn ghost block small" data-act="cat" data-cat="problemi" data-from="dafare">Altri ${open.length - 5}</button>` : ''}`
    : `<div class="card quiet">Nessun problema aperto. <button type="button" class="link-btn inline" data-act="new-issue">Segnala</button></div>`;
  return `<div class="section-title">${icon('alert')}Problemi ${open.length ? `<span class="count">${open.length}</span>` : ''}${link}</div>${body}`;
}

async function doneTask(id) {
  try {
    const row = await S.api.completeTask(id);
    replaceTask(row);
    render();
    toast(row.done ? 'Fatto' : `Fatto, la prossima volta è ${dueLabel(row).text}`, {
      label: 'Annulla',
      fn: async () => { try { replaceTask(await S.api.undoTask(id)); render(); } catch (e) { toast(e.message); } },
    });
  } catch (e) { toast(e.message); }
}

function openTask(id) {
  const t = S.tasks.find((x) => x.id === id);
  if (!t) return;
  const who = t.assigned_to ? (t.assigned_to === S.uid ? 'Tu' : person(t.assigned_to)?.full_name || '—') : 'Chiunque';
  openSheet(t.title, `<dl class="kv">
      <dt>Quando</dt><dd>${esc(repeatLabel(t.repeat_days))}${t.done ? '' : `, prossima volta ${esc(dueLabel(t).text)}`}</dd>
      <dt>Chi</dt><dd>${esc(who)}</dd>
      ${t.location ? `<dt>Dove</dt><dd>${esc(t.location)}</dd>` : ''}
      ${t.notes ? `<dt>Note</dt><dd>${esc(t.notes)}</dd>` : ''}
    </dl>
    ${t.done ? '' : `<div class="row"><button type="button" class="btn primary" data-a="done">${icon('check')}Fatto</button><button type="button" class="btn" data-a="snooze">${icon('clock')}Rimanda</button></div>`}
    <div class="section-title">${icon('history')}Ultime volte</div>
    <div id="tlog" class="card log"><div class="log-row muted">Carico…</div></div>
    <div class="row" style="margin-top:14px">
      <button type="button" class="btn" data-a="edit">${icon('edit')}Modifica</button>
      <button type="button" class="btn danger" data-a="delete">${icon('trash')}Elimina</button></div>`, (sh) => {
    S.api.taskLog(id).then((rows) => {
      const el = $('#tlog', sh);
      if (el) el.innerHTML = rows.length ? rows.map((r) => `<div class="log-row"><b>${esc(r.user_id === S.uid ? 'Tu' : person(r.user_id)?.full_name || 'Qualcuno')}</b><span>${esc(fmtWhen(r.done_at))}</span>${r.note ? `<q>${esc(r.note)}</q>` : ''}</div>`).join('')
        : '<div class="log-row muted">Ancora nessuno</div>';
    }).catch(() => {});
    sh.addEventListener('click', (e) => {
      const a = e.target.closest('[data-a]')?.dataset.a;
      if (a === 'done') { closeSheet(); doneTask(id); }
      if (a === 'snooze') snoozeTask(id);
      if (a === 'edit') taskForm(t);
      if (a === 'delete') confirmSheet('Eliminare il compito?', `${t.title} sparirà per tutti.`, 'Elimina', true, async () => {
        try { await S.api.deleteTask(id); S.tasks = S.tasks.filter((x) => x.id !== id); render(); toast('Eliminato'); } catch (x) { toast(x.message); }
      });
    });
  });
}

const TASK_IDEAS = ['Riempire i puntali', 'Autoclave', 'Prendere acqua distillata', 'Pulizia banconi', 'Pulizia cappa', 'Svuotare i rifiuti biologici'];
const FREQS = [[0, 'Una volta'], [1, 'Ogni giorno'], [2, 'Ogni 2 giorni'], [7, 'Ogni settimana'], [14, 'Ogni 2 settimane'], [30, 'Ogni mese']];

function placeOptions() {
  return [...new Set([...S.items.map((i) => locRoot(i.location)), ...S.instruments.map((i) => i.name)].filter(Boolean))].sort(byNatural);
}

function taskForm(t = null, preset = null) {
  const v = t || { repeat_days: 7, due_on: todayKey(), ...preset };
  const withInst = !!(v.instrument_id || preset?.instrument_id);
  const custom = v.repeat_days && !FREQS.some(([n]) => n === v.repeat_days);
  const members = S.profiles.filter((p) => p.role !== 'pending').sort((a, b) => a.full_name.localeCompare(b.full_name, 'it'));
  openSheet(t ? 'Modifica compito' : 'Nuovo compito', `<form id="f" autocomplete="off">
    <label class="field"><span>Cosa c'è da fare</span><input name="title" required maxlength="100" value="${esc(v.title)}" placeholder="es. Autoclave"></label>
    ${t ? '' : `<div class="seg ideas">${TASK_IDEAS.map((x) => `<button type="button" class="chip" data-idea="${esc(x)}">${esc(x)}</button>`).join('')}</div>`}
    <div class="field"><span>Quanto spesso</span>
      <div class="seg">${FREQS.map(([n, l]) => `<button type="button" class="chip" data-freq="${n}" aria-pressed="${!custom && (v.repeat_days || 0) === n}">${l}</button>`).join('')}<button type="button" class="chip" data-freq="x" aria-pressed="${!!custom}">Altro</button></div>
      <label class="every ${custom ? '' : 'hidden'}">Ogni <input name="every" type="number" inputmode="numeric" min="1" max="365" value="${custom ? v.repeat_days : 3}" class="input"> giorni</label></div>
    <label class="field"><span id="due-label">${v.repeat_days ? 'Prima volta' : 'Entro il'}</span><input name="due_on" type="date" required value="${esc(v.due_on)}"></label>
    ${withInst ? `<label class="field"><span>Strumento</span><select name="instrument_id"><option value="">Nessuno</option>${S.instruments.map((i) => `<option value="${i.id}" ${i.id === v.instrument_id ? 'selected' : ''}>${esc(i.name)}</option>`).join('')}</select></label>` : ''}
    <label class="field"><span>Chi</span><select name="assigned_to"><option value="">Chiunque</option>${members.map((p) => `<option value="${p.id}" ${v.assigned_to === p.id ? 'selected' : ''}>${esc(p.id === S.uid ? `${p.full_name} (tu)` : p.full_name)}</option>`).join('')}</select></label>
    <label class="field"><span>Dove (facoltativo)</span><input name="location" list="tplaces" maxlength="80" value="${esc(v.location)}"></label>
    <label class="field"><span>Note (facoltative)</span><textarea name="notes" maxlength="300">${esc(v.notes)}</textarea></label>
    <datalist id="tplaces">${placeOptions().map((l) => `<option value="${esc(l)}">`).join('')}</datalist>
    <p class="err" id="err"></p>
    <button class="btn primary block" type="submit">${t ? 'Salva' : 'Aggiungi compito'}</button></form>`, (sh) => {
    const f = $('#f', sh).elements;
    let freq = custom ? 'x' : String(v.repeat_days || 0);
    sh.querySelectorAll('[data-idea]').forEach((b) => (b.onclick = () => { f.title.value = b.dataset.idea; }));
    sh.querySelectorAll('[data-freq]').forEach((b) => (b.onclick = () => {
      freq = b.dataset.freq;
      sh.querySelectorAll('[data-freq]').forEach((x) => x.setAttribute('aria-pressed', String(x === b)));
      $('.every', sh).classList.toggle('hidden', freq !== 'x');
      $('#due-label', sh).textContent = freq === '0' ? 'Entro il' : 'Prima volta';
    }));
    $('#f', sh).onsubmit = (e) => {
      e.preventDefault();
      const repeat = freq === 'x' ? Math.max(1, Math.min(365, parseInt(f.every.value, 10) || 1)) : Number(freq) || null;
      const payload = { title: f.title.value.trim(), repeat_days: repeat, due_on: f.due_on.value || todayKey(), assigned_to: f.assigned_to.value || null, location: strOrNull(f.location.value), notes: strOrNull(f.notes.value), instrument_id: f.instrument_id ? f.instrument_id.value || null : v.instrument_id ?? null };
      if (!payload.title) { $('#err', sh).textContent = 'Scrivi cosa c\'è da fare'; return; }
      if (t) payload.id = t.id;
      busy(e.submitter, async () => {
        try {
          const row = await S.api.saveTask(payload); replaceTask(row); S.todo = 'compiti';
          if (preset?.instrument_id && !t) { render(); openInstrument(preset.instrument_id); toast('Manutenzione programmata, compare anche in Da fare'); }
          else { closeSheet(); render(); toast(t ? 'Salvato' : 'Compito aggiunto'); }
        } catch (x) { $('#err', sh).textContent = x.message; }
      });
    };
  });
}

// ---------- problemi e incidenti ----------
const URGENCY = { bassa: 'Può aspettare', normale: 'Normale', alta: 'Urgente' };
const SEVERITY = { bassa: 'Lieve', normale: 'Media', alta: 'Grave' };
const INC_TYPES = { sversamento: 'Sversamento', ferita: 'Ferita o taglio', esposizione: 'Esposizione o inalazione', ustione: 'Ustione', contaminazione: 'Contaminazione di colture', guasto: 'Guasto con rischio', quasi: 'Quasi incidente', altro: 'Altro' };
const isIncident = (i) => i.kind === 'incidente';
const kindIssues = (kind) => S.issues.filter((i) => (isIncident(i) ? 'incidente' : 'problema') === kind);
const instIssues = (instId) => openIssues().filter((i) => i.instrument_id === instId && !isIncident(i));
const issueState = (i) => (i.status === 'risolto' ? `${isIncident(i) ? 'Chiuso' : 'Risolto'} da ${nameOf(i.resolved_by)} ${ago(i.resolved_at)}`
  : i.status === 'in_corso' ? `Se ne occupa ${i.taken_by === S.uid ? 'te' : nameOf(i.taken_by)}` : isIncident(i) ? 'Da verificare' : 'Da risolvere');

function issueBadges(i) {
  const b = [];
  if (isIncident(i)) {
    if (i.incident_type) b.push(`<span class="badge muted">${esc(INC_TYPES[i.incident_type] || i.incident_type)}</span>`);
    b.push(`<span class="badge ${i.urgency === 'alta' ? 'danger' : i.urgency === 'normale' ? 'warn' : 'muted'}">${icon('shield')}${SEVERITY[i.urgency] || ''}</span>`);
  } else if (i.urgency === 'alta' && i.status !== 'risolto') b.push(`<span class="badge danger">${icon('alert')}Urgente</span>`);
  if (i.instrument_id) { const ins = S.instruments.find((x) => x.id === i.instrument_id); if (ins) b.push(`<span class="badge info">${icon('tool')}${esc(ins.name)}</span>`); }
  if (i.status === 'in_corso') b.push(`<span class="badge info">${icon('user')}Se ne occupa ${esc(i.taken_by === S.uid ? 'te' : nameOf(i.taken_by))}</span>`);
  if (i.status === 'risolto') b.push(`<span class="badge ok">${icon('check')}${isIncident(i) ? 'Chiuso' : 'Risolto'}</span>`);
  return b.join('');
}

function issueCard(i) {
  const thumb = i.photos?.length
    ? `<img class="thumb" data-photo="${esc(i.photos[0])}" src="${esc(pic(i.photos[0]))}" alt="">`
    : `<div class="cat-ic">${icon(isIncident(i) ? 'shield' : 'alert')}</div>`;
  const when = isIncident(i) && i.happened_at ? fmtWhen(i.happened_at) : `${nameOf(i.created_by)} ${ago(i.created_at)}`;
  const meta = [i.location, when].filter(Boolean).join(' · ');
  return `<div class="item issue" data-act="open-issue" data-id="${i.id}" role="button" tabindex="0">${thumb}
    <div class="body"><div class="name">${esc(i.title)}</div><div class="meta">${esc(meta)}${i.comments ? ` · ${i.comments} ${i.comments === 1 ? 'aggiornamento' : 'aggiornamenti'}` : ''}</div>
    <div class="tags">${issueBadges(i)}</div></div>${icon('chev', 'chev')}</div>`;
}

function issuesList() {
  const inc = S.issueKind === 'incidente';
  const showDone = S.issueFilter === 'risolti';
  const all = kindIssues(inc ? 'incidente' : 'problema');
  const list = all.filter((i) => (i.status === 'risolto') === showDone);
  const nOpen = all.filter((i) => i.status !== 'risolto').length;
  const chip = (v, l) => `<button type="button" class="chip" data-act="issue-filter" data-v="${v}" aria-pressed="${S.issueFilter === v}">${l}</button>`;
  const head = `<div class="chips">${chip('aperti', `${inc ? 'Da verificare' : 'Da risolvere'} (${nOpen})`)}${chip('risolti', inc ? 'Chiusi di recente' : 'Risolti di recente')}</div>`;
  const safety = inc ? `<div class="banner safety">${icon('shield')}<div>${esc(CONFIG.EMERGENZA || 'In caso di emergenza chiama il 112.')} Le precauzioni e il primo soccorso di ogni reagente sono nella sua scheda di sicurezza, in Inventario.</div></div>` : '';
  if (!list.length) {
    const title = showDone ? (inc ? 'Nessun incidente chiuso di recente' : 'Niente risolto di recente') : (inc ? 'Nessun incidente da verificare' : 'Nessun problema aperto');
    const text = showDone ? '' : inc ? 'Sversamenti, ferite, esposizioni, contaminazioni e quasi incidenti vanno registrati qui, anche se piccoli: servono a evitare che si ripetano.' : 'Se qualcosa si rompe o non va, segnalalo con una foto dal tasto in basso.';
    return head + safety + `<div class="empty">${icon('checkCircle')}<b>${title}</b>${text}</div>`;
  }
  const order = { alta: 0, normale: 1, bassa: 2 };
  if (!showDone) list.sort((a, b) => order[a.urgency] - order[b.urgency] || b.created_at.localeCompare(a.created_at));
  else list.sort((a, b) => (b.resolved_at || '').localeCompare(a.resolved_at || ''));
  return head + safety + `<div class="list" style="margin-top:10px">${list.map(issueCard).join('')}</div>`;
}

// per gli amministratori: il registro completo degli incidenti, da conservare
async function incidentsCsv() {
  try {
    const rows = await S.api.incidents();
    if (!rows.length) { toast('Nessun incidente registrato'); return; }
    const when = (x) => (x ? new Date(x).toLocaleString('it-IT', { dateStyle: 'short', timeStyle: 'short' }) : '');
    const out = [['Data e ora', 'Tipo', 'Gravità', 'Dove', 'In breve', 'Coinvolti', 'Prodotto', 'Fatto subito', 'Dettagli', 'Registrato da', 'Stato', 'Chiuso il', 'Chiuso da']];
    for (const i of rows) out.push([when(i.happened_at || i.created_at), INC_TYPES[i.incident_type] || i.incident_type || '', SEVERITY[i.urgency] || '', i.location || '', i.title, i.involved || '',
      S.items.find((x) => x.id === i.item_id)?.name || '', i.actions || '', i.description || '', person(i.created_by)?.full_name || '', i.status === 'risolto' ? 'chiuso' : i.status === 'in_corso' ? 'in verifica' : 'aperto',
      when(i.resolved_at), person(i.resolved_by)?.full_name || '']);
    downloadCsv(out, `registro-incidenti-${todayKey()}.csv`);
  } catch (e) { toast(e.message); }
}

// cosa dice la scheda di sicurezza del prodotto coinvolto (pittogrammi e frasi di risposta)
function firstAidHtml(it) {
  if (!it) return '';
  const s = it.sds;
  const found = s && !s.none && !s.nf;
  const pict = (found && !sdsNc(s) ? s.pict : (it.hazards || [])).map((id) => GHS.find((g) => g.id === id)).filter(Boolean);
  const resp = (found ? s.p || [] : []).filter((c) => /^P3/.test(c));
  const body = !found && !pict.length
    ? `<p class="hint" style="margin:0">Per ${esc(it.name)} non c'è ancora una scheda nell'app: aprila dall'articolo e cercala.</p>`
    : `${pict.length ? `<div class="ghs-row">${pict.map((g) => `<div class="ghs-item">${ghsIcon(g)}<span>${esc(g.label)}</span></div>`).join('')}</div>` : ''}
       ${resp.length ? `<ul class="sds-list">${resp.map((c) => `<li><b>${esc(c)}</b> ${esc(P_IT[c] || c.split('+').map((x) => P_IT[x] || '').filter(Boolean).join('. '))}</li>`).join('')}</ul>` : '<p class="hint" style="margin:0 0 8px">La scheda non riporta frasi di risposta particolari.</p>'}`;
  return `<div class="section-title">${icon('shield')}Dalla scheda di sicurezza</div><div class="card sds"><div class="sds-head"><b>${esc(it.name)}</b></div>${body}
    <button type="button" class="btn ghost block" data-a="item">${icon('boxes')}Apri l'articolo</button></div>`;
}

// giro 25: negli elenchi le miniature, la foto intera solo dove serve grande (img con data-full, ingrandimenti, tavole, stampe)
// pic(path): l'indirizzo della miniatura se c'è già, altrimenti la foto intera se la miniatura manca o la foto è appena scattata
function pic(path) {
  if (!path) return '';
  const full = S.photoUrls[path];
  if (full && /^(blob|data):/.test(full)) return full;
  return S.thumbUrls[path] || (S.thumbMiss.has(path) ? full || '' : '');
}
function fillPhotos(scope = document) {
  const imgs = [...scope.querySelectorAll('img[data-photo]')].filter((i) => !i.getAttribute('src'));
  if (!imgs.length) return;
  const full = [], thumbs = [];
  for (const i of imgs) (i.hasAttribute('data-full') || S.thumbMiss.has(i.dataset.photo) ? full : thumbs).push(i.dataset.photo);
  ensurePhotoUrls(full, thumbs);
}

// paths: foto intere; thumbs: foto di cui basta la miniatura
async function ensurePhotoUrls(paths, thumbs = []) {
  if (Date.now() - S.photoUrlsAt > 5 * 3600e3) { S.photoUrls = staticAware(); S.thumbUrls = staticAware(); S.photoUrlsAt = Date.now(); }
  const tNeed = [...new Set(thumbs)].filter((p) => p && !pic(p) && !S.thumbMiss.has(p));
  const need = [...new Set(paths)].filter((p) => p && !S.photoUrls[p]);
  if (need.length || tNeed.length) {
    try {
      const got = await S.api.photoUrls([...need, ...tNeed.map(thumbOf)]);
      for (const p of need) if (got[p]) S.photoUrls[p] = got[p];
      // le foto senza miniatura (caricate prima del giro 25): si usa quella intera
      const miss = [];
      for (const p of tNeed) { const u = got[thumbOf(p)]; if (u) S.thumbUrls[p] = u; else { S.thumbMiss.add(p); if (!S.photoUrls[p]) miss.push(p); } }
      if (miss.length) Object.assign(S.photoUrls, await S.api.photoUrls(miss));
    } catch { return; }
  }
  document.querySelectorAll('img[data-photo]').forEach((img) => {
    const p = img.dataset.photo, u = img.hasAttribute('data-full') ? S.photoUrls[p] : pic(p);
    if (u && img.getAttribute('src') !== u) img.src = u;
  });
}

// la foto di uno strumento: ritaglio 4:3 al centro, 400×300, salvata come testo nella riga dello strumento (circa 25 kB)
async function instThumb(file) {
  let src, w, h;
  try { src = await createImageBitmap(file); w = src.width; h = src.height; } catch {
    const url = URL.createObjectURL(file); src = new Image(); src.src = url; await src.decode(); w = src.naturalWidth; h = src.naturalHeight; URL.revokeObjectURL(url);
  }
  const cw = Math.min(w, h * 4 / 3), ch = cw * 3 / 4, c = document.createElement('canvas');
  c.width = 400; c.height = 300;
  c.getContext('2d').drawImage(src, (w - cw) / 2, (h - ch) / 2, cw, ch, 0, 0, 400, 300);
  const u = c.toDataURL('image/jpeg', 0.7);
  if (!u.startsWith('data:image/jpeg')) throw new Error('Foto non leggibile');
  return u;
}
async function compressImage(file, max = 1600, quality = 0.8) {
  let src, w, h;
  try {
    src = await createImageBitmap(file);
    w = src.width; h = src.height;
  } catch {
    const url = URL.createObjectURL(file);
    src = new Image();
    src.src = url;
    await src.decode();
    w = src.naturalWidth; h = src.naturalHeight;
    URL.revokeObjectURL(url);
  }
  const k = Math.min(1, max / Math.max(w, h));
  const canvas = document.createElement('canvas');
  canvas.width = Math.round(w * k); canvas.height = Math.round(h * k);
  canvas.getContext('2d').drawImage(src, 0, 0, canvas.width, canvas.height);
  const blob = await new Promise((res) => canvas.toBlob(res, 'image/jpeg', quality));
  if (!blob) throw new Error('Foto non leggibile');
  return blob;
}

function viewPhoto(path, cap = '') {
  const url = S.photoUrls[path] || pic(path);
  const el = document.createElement('div');
  el.className = 'lightbox';
  el.setAttribute('role', 'dialog');
  el.setAttribute('aria-label', 'Foto');
  el.innerHTML = `<img data-photo="${esc(path)}" data-full src="${esc(url)}" alt="${esc(cap || 'Foto')}">${cap ? `<p class="lb-cap">${esc(cap)}</p>` : ''}<button type="button" class="close" aria-label="Chiudi">${icon('x')}</button>`;
  el.onclick = () => el.remove();
  document.body.appendChild(el);
  if (!S.photoUrls[path]) ensurePhotoUrls([path]);
}

function photoPicker(sh, photos, max = 6) {
  const draw = () => {
    $('#ph', sh).innerHTML = photos.map((p, k) => `<div class="photo"><img src="${p.url}" alt=""><button type="button" class="ph-x" data-k="${k}" aria-label="Togli la foto">${icon('x')}</button></div>`).join('');
  };
  $('#pin', sh).onchange = async (e) => {
    for (const file of [...e.target.files].slice(0, Math.max(0, max - photos.length))) {
      try { const blob = await compressImage(file); photos.push({ blob, url: URL.createObjectURL(blob) }); } catch { toast('Una foto non si riesce a leggere'); }
    }
    e.target.value = '';
    draw();
  };
  sh.addEventListener('click', (e) => {
    const x = e.target.closest('.ph-x');
    if (x) { photos.splice(Number(x.dataset.k), 1); draw(); }
  });
}
const photoField = () => `<div class="field"><span>Foto</span><div class="photos" id="ph"></div>
      <label class="btn block file-btn">${icon('camera')}Aggiungi foto<input type="file" id="pin" accept="image/*" multiple></label></div>`;

function issueForm(pre = {}) {
  const photos = [];
  const insts = S.instruments.filter((x) => x.active).sort((a, b) => byNatural(a.name, b.name));
  openSheet('Segnala un problema', `<form id="f" autocomplete="off">
    <label class="field"><span>Cosa non va</span><input name="title" required maxlength="100" placeholder="es. La centrifuga fa un rumore strano"></label>
    ${insts.length ? `<label class="field"><span>Strumento (se riguarda uno strumento)</span><select name="instrument_id"><option value="">Nessuno</option>${insts.map((x) => `<option value="${x.id}" ${pre.instrument_id === x.id ? 'selected' : ''}>${esc(x.name)}</option>`).join('')}</select>
      <span class="hint">Chi va a prenotarlo vede subito che c'è un problema</span></label>` : ''}
    ${photoField()}
    <label class="field"><span>Dettagli (facoltativi)</span><textarea name="description" maxlength="1000" placeholder="Cosa è successo, cosa hai già provato"></textarea></label>
    <label class="field"><span>Dove</span><input name="location" list="iplaces" maxlength="80" placeholder="es. Stanza 205, Cappa chimica" value="${esc(pre.location || '')}"></label>
    <div class="field"><span>Urgenza</span><div class="seg">${Object.entries(URGENCY).map(([u, l]) => `<button type="button" class="chip" data-urg="${u}" aria-pressed="${u === 'normale'}">${l}</button>`).join('')}</div></div>
    <datalist id="iplaces">${placeOptions().map((l) => `<option value="${esc(l)}">`).join('')}</datalist>
    <p class="err" id="err"></p>
    <button class="btn primary block" type="submit">${icon('bell')}Segnala a tutti</button></form>`, (sh) => {
    let urgency = 'normale';
    photoPicker(sh, photos);
    const f = $('#f', sh).elements;
    if (f.instrument_id) f.instrument_id.addEventListener('change', () => { const ins = S.instruments.find((x) => x.id === f.instrument_id.value); if (ins?.location && !f.location.value) f.location.value = ins.location; });
    sh.addEventListener('click', (e) => {
      const u = e.target.closest('[data-urg]');
      if (u) { urgency = u.dataset.urg; sh.querySelectorAll('[data-urg]').forEach((b) => b.setAttribute('aria-pressed', String(b === u))); }
    });
    $('#f', sh).onsubmit = (e) => {
      e.preventDefault();
      const title = f.title.value.trim();
      if (!title) return;
      busy(e.submitter, async () => {
        try {
          const paths = [];
          for (const p of photos) paths.push(await S.api.uploadPhoto(p.blob));
          const row = await S.api.saveIssue({ kind: 'problema', title, description: strOrNull(f.description.value), location: strOrNull(f.location.value), urgency, photos: paths, instrument_id: f.instrument_id?.value || null });
          photos.forEach((p, k) => { S.photoUrls[paths[k]] = p.url; });
          S.issues.unshift(row);
          S.issueFilter = 'aperti'; S.issueKind = 'problema'; if (S.cat !== 'problemi') { S.tab = 'inventario'; S.cat = 'problemi'; S.catStack = []; S.catBackTab = 'dafare'; }
          closeSheet(); render();
          toast('Segnalato a tutto il laboratorio');
          S.api.notify().catch(() => {});
        } catch (x) { $('#err', sh).textContent = x.message; }
      });
    };
  });
}

