        if (r.source_kind !== undefined) { const v = xlStr(r.source_kind); source_kind = v ? pick(SAMPLE_SOURCES, v) || (/^da /.test(norm(v)) ? pick(SAMPLE_SOURCES, norm(v).slice(3)) : undefined) : null; if (v && !source_kind) errs.push(`"${v}" in Viene da non è previsto, scegli dal menu`); }
        const q = r.quantity === undefined ? undefined : xlNum(r.quantity);
