const SIGNAL_IT = { Danger: 'Pericolo', Warning: 'Attenzione' };
const PUBCHEM = 'https://pubchem.ncbi.nlm.nih.gov/rest';
const sdsIsChem = (it) => ['reagenti', 'solventi', 'standard'].includes(it.category);
// terreni, zuccheri e polimeri di solito non classificati: non si cercano in blocco e non contano fra le schede da sistemare
// (non il gel di silice, che con l'indicatore al cobalto è cancerogeno, né la Celite, che contiene silice cristallina)
const SDS_USUAL = /\b(?:agar|agaros\w*|broth|brodo|pda|pdb|lb|peptone|tri?ptone|tryptone|yeast extract|estratto di lievito|malt extract|estratto di malto|dextrose|destrosio|d?\s?glucosio|saccarosio|sucrose|czapek\w*|corn ?meal|oat ?meal|afpa|sephadex|cellulosa|cellulose|amido|starch|inulina|xilano|xylan|pectina|caseina|chitosan|reishi|tamponi per phmetro|acido poligatt?uronico|polygalacturonic)\b/i;
const sdsUsual = (it) => SDS_USUAL.test(cleanName(it.name || '')) && !(it.hazards || []).length && !it.sds?.pict?.length && !it.sds?.h?.length;
const sdsMissing = () => S.items.filter((i) => sdsIsChem(i) && !i.sds && !sdsUsual(i) && Number(i.quantity) !== 0);
const sdsHas = (s) => !!s && (s.pict?.length || s.h?.length || s.cid);

async function pubchemJson(url) {
  const r = await fetch(url, { headers: { accept: 'application/json' } });
  if (r.status === 404) return null;
  if (!r.ok) throw new Error('PubChem non risponde, riprova tra poco');
  return r.json();
}

// Cerca il composto per nome e legge la classificazione GHS (quella aggregata dalle notifiche ECHA e dei fornitori)
async function pubchemLookup(name) {
  const d = await pubchemJson(`${PUBCHEM}/pug/compound/name/${encodeURIComponent(name)}/cids/JSON`);
  const cid = d?.IdentifierList?.CID?.[0];
  if (!cid) return null;
  const [prop, view] = await Promise.all([
    pubchemJson(`${PUBCHEM}/pug/compound/cid/${cid}/property/Title,MolecularFormula/JSON`),
    pubchemJson(`${PUBCHEM}/pug_view/data/compound/${cid}/JSON?heading=GHS+Classification`),
  ]);
  const p = prop?.PropertyTable?.Properties?.[0] || {};
  const out = { cid, title: p.Title || name, formula: p.MolecularFormula || null, matched: name, signal: null, pict: [], h: [], p: [], nc: 0, at: todayKey(), src: 'pubchem' };
  const find = (sec) => { for (const s of sec?.Section || []) { if (s.TOCHeading === 'GHS Classification') return s; const r = find(s); if (r) return r; } return null; };
  const sec = find(view?.Record);
  if (!sec) return { ...out, none: true };
  let gp = false, gs = false, gh = false, gpc = false, gn = false;
  for (const i of sec.Information || []) {
    const sw = i.Value?.StringWithMarkup || [];
    if (i.Name === 'Pictogram(s)' && !gp) { for (const m of sw[0]?.Markup || []) { const mm = /(GHS0\d)/.exec(m.URL || ''); if (mm && !out.pict.includes(mm[1])) out.pict.push(mm[1]); } gp = true; }
    else if (i.Name === 'Signal' && !gs) { out.signal = sw[0]?.String?.trim() || null; gs = true; }
    else if (i.Name === 'GHS Hazard Statements' && !gh) {
      for (const x of sw) { const mm = /^\s*((?:H|EUH)\d{3}[A-Za-z]*(?:\+(?:H|EUH)\d{3}[A-Za-z]*)*)(?:\s*\((\d+(?:\.\d+)?)%\))?/.exec(x.String); if (mm && !out.h.some((y) => y.c === mm[1])) out.h.push({ c: mm[1], pct: mm[2] ? Number(mm[2]) : null }); }
      gh = true;
    } else if (i.Name === 'Precautionary Statement Codes' && !gpc) { out.p = (sw[0]?.String || '').match(/P\d{3}(?:\+P\d{3})*/g) || []; gpc = true; }
    else if (i.Name === 'Note' && !gn) { const mm = /does not meet GHS hazard criteria for\s*<?\s*(\d+(?:\.\d+)?)%/.exec(sw[0]?.String || ''); out.nc = mm ? Number(mm[1]) : 0; gn = true; }
  }
  return out;
}

// nomi da provare, nell'ordine: il nome pulito, poi gli "altri nomi" scritti nelle note
function sdsCandidates(it) {
  const clean = (n) => String(n || '').replace(/\s*\(n\.\s*[^)]*\)\s*/g, ' ').replace(/\b\d+(?:[.,]\d+)?\s*(?:ml|l|g|kg|mg|µl|pz|conf\.?)\b/gi, ' ')
    .replace(/\b(?:lc-?ms|hplc|grade|per\s+hplc|per\s+analisi|\d{1,3}\s*%|anhydrous|ultrapure|sigma|merck|fluka|carlo erba|vwr|honeywell|aldrich|supelco|difco|himedia|oxoid)\b/gi, ' ')
    .replace(/[,:;/]+/g, ' ').replace(/\s+/g, ' ').trim();
  const out = [clean(it.name)];
  for (const part of String(it.notes || '').split(/\s*;\s*/)) { const m = /^altro nome:\s*(.+)/i.exec(part.trim()); if (m) out.push(clean(m[1])); }
  return [...new Set(out.filter((x) => x.length > 1))];
}

async function sdsSearchItem(it, names = null) {
  for (const n of names || sdsCandidates(it)) {
    const r = await pubchemLookup(n);
    if (r) return r;
  }
  return null;
}

// "non classificato" vale solo se nessuna frase di pericolo è ufficiale (senza percentuale, la classificazione armonizzata)
// o segnalata dalla maggioranza: PubChem per l'acido propionico dà 100% non classificato accanto all'H314 armonizzata
// eccezioni note: cloruro di sodio (CID 5234), che PubChem lega per errore a frasi H senza percentuale
const SDS_SAFE_CIDS = new Set([5234]);
const sdsNc = (s) => !!s && ((s.cid && SDS_SAFE_CIDS.has(Number(s.cid))) || (s.nc >= 50 && !(s.h || []).some((h) => h.pct == null || h.pct >= 50)));
function hazardsFromSds(s) {
  // pittogrammi segnalati dalla maggioranza delle notifiche; se un prodotto è "non classificato" per quasi tutti, niente pittogrammi
  if (!s || sdsNc(s)) return [];
  return s.pict || [];
}

async function applySds(it, sds) {
  const patch = { sds };
  if (sds && !(it.hazards || []).length) patch.hazards = hazardsFromSds(sds);
  const row = await S.api.patchItem(it.id, patch);
  replaceItem(row);
  return row;
}

