  for (const t of DPI_TEXT) if (t.re.test(text)) { for (const [k, v] of Object.entries(t.gear)) if (!(k in gear) || (!gear[k] && v)) gear[k] = gear[k] || v; rows.push({ name: t.n, d: { gear: t.gear, notes: [t.note] } }); }
