const COPY_EVERY = { settimana: 7, mese: 30, mai: 0 };
const copyLater = () => { try { return Number(localStorage.getItem('labapp-copy-later') || 0); } catch { return 0; } };
function copyReminderHtml() {
  if (DEMO_PREVIEW || Date.now() < copyLater()) return '';
  const pf = prefs(), now = Date.now();
  const due = (every, last, since) => { const d = COPY_EVERY[every ?? 'mese']; return !!d && !!(last || since) && now - Date.parse(last || since) > d * 864e5; };
  if (isAdmin() && due(pf.labCopyEvery, pf.lastLabCopy, S.me?.created_at)) {
    return `<div class="card install-card copy-card"><div class="ic">${icon('shield')}</div><div class="grow"><b>Salva una copia del laboratorio</b>
      <div class="sub">${pf.lastLabCopy ? `L'ultima copia fuori dal server è di ${esc(ago(pf.lastLabCopy))}.` : 'Non ne hai ancora salvata una fuori dal server.'} Tutti i dati e, se vuoi, le foto, in un file da tenere sul PC o su Drive.</div>
      <div class="row" style="margin-top:10px"><button type="button" class="btn primary" data-act="copy-lab">Salva</button><button type="button" class="btn ghost" data-act="copy-later">Più tardi</button></div></div></div>`;
  }
  const first = (S.journal || []).at(-1)?.created_at;
  if (first && due(pf.diaryCopyEvery, pf.lastDiaryCopy, first)) {
    return `<div class="card install-card copy-card"><div class="ic">${icon('file')}</div><div class="grow"><b>Salva una copia del tuo diario</b>
      <div class="sub">${pf.lastDiaryCopy ? `L'ultima è di ${esc(ago(pf.lastDiaryCopy))}.` : 'Un PDF con tutte le pagine e le foto, da tenere sul PC o su Drive.'}</div>
      <div class="row" style="margin-top:10px"><button type="button" class="btn primary" data-act="copy-diary">Salva</button><button type="button" class="btn ghost" data-act="copy-later">Più tardi</button></div></div></div>`;
  }
  return '';
}
function copySettingsHtml(key, label) {
  const v = prefs()[key] ?? 'mese';
  return `<div class="field"><span>${label}</span><div class="seg">${Object.keys(COPY_EVERY).map((k) => `<button type="button" class="chip" data-every="${key}:${k}" aria-pressed="${v === k}">${k === 'mai' ? 'Mai' : `Ogni ${k}`}</button>`).join('')}</div></div>`;
}
function bindCopySettings(sh) {
  sh.addEventListener('click', (e) => {
    const b = e.target.closest('[data-every]'); if (!b) return;
    const [key, v] = b.dataset.every.split(':');
    sh.querySelectorAll(`[data-every^="${key}:"]`).forEach((x) => x.setAttribute('aria-pressed', String(x === b)));
    savePrefs({ [key]: v });
  });
}
function diaryCopySheet() {
  const pf = prefs();
  openSheet('Copia del mio diario', `<p class="hint" style="margin-top:0">Il diario è già sul server del laboratorio e nella copia di ogni notte. Una copia tua, sul PC o su Drive, lo tiene al sicuro anche fra anni.${pf.lastDiaryCopy ? ` L'ultima l'hai salvata ${esc(ago(pf.lastDiaryCopy))}.` : ''}</p>
    <div class="row"><button type="button" class="btn primary" data-a="pdf">${icon('file')}PDF di tutto il diario</button><button type="button" class="btn" data-a="more">${icon('filter')}Scegli cosa</button></div>
    ${copySettingsHtml('diaryCopyEvery', 'Ricordamelo')}`, (sh) => {
    bindCopySettings(sh);
    sh.addEventListener('click', (e) => {
      const a = e.target.closest('[data-a]')?.dataset.a;
      if (a === 'more') { S.diaryWho = S.uid; diaryExportSheet({ proj: '', from: '', to: '', q: '' }); }
      if (a === 'pdf') busy(e.target.closest('button'), async () => {
        try { S.diaryWho = S.uid; await loadDiaryExtra(S.uid); if (await exportDiary({ who: S.uid, proj: '', from: '', to: '', q: '', runs: true, books: false, photos: true }, 'pdf', canShareFiles() ? 'share' : 'save')) { savePrefs({ lastDiaryCopy: new Date().toISOString() }); closeSheet(); } } catch (x) { toast(x.message); }
      });
    });
  });
}

const TABLE_LABEL = { items: 'Inventario', strains: 'Ceppi', protocols: 'Protocolli', protocol_runs: 'Esecuzioni', lab_journal: 'Pagine del diario', lab_projects: 'Progetti', instruments: 'Strumenti', tasks: 'Compiti',
  issues: 'Problemi e incidenti', cylinders: 'Bombole', flowcells: 'Flow cell', freezers: 'Congelatori', boxes: 'Scatole', practicals: 'Esercitazioni', funds: 'Fondi', lc_columns: 'Colonne', waste_containers: 'Rifiuti', order_requests: 'Richieste d\'ordine', bookings: 'Prenotazioni', profiles: 'Persone' };
const fmtBytes = (n) => (n > 1e6 ? `${fmtN(Math.round(n / 1e5) / 10)} MB` : `${Math.max(1, Math.round(n / 1e3))} kB`);

function openBackups() {
  openSheet('Copie di sicurezza', '<div id="bk"><div class="spin" aria-label="Caricamento"></div></div>', (sh) => {
    bindCopySettings(sh);
    const load = async () => {
      let list;
      try { list = await S.api.backups(); } catch (x) { $('#bk', sh).innerHTML = `<p class="err">${esc(/backups/.test(x.message) ? 'Per le copie va aggiornato il database (schema.sql)' : x.message)}</p>`; return; }
      const lastAuto = list.find((b) => b.kind === 'auto');
      const stale = !lastAuto || Date.now() - Date.parse(lastAuto.made_at) > 36 * 3600e3;
      const pf = prefs();
      $('#bk', sh).innerHTML = `<p class="hint" style="margin-top:0">Ogni notte verso le 3 il server copia tutti i dati (il piano gratuito di Supabase non lo fa). Restano le ultime notti, una a settimana per un mese e una al mese per sei mesi. Le foto non sono nelle copie del server: si salvano con la copia sul PC.</p>
        ${stale ? `<div class="banner warn">${icon('alert')}<div>${lastAuto ? `L'ultima copia notturna è di ${esc(ago(lastAuto.made_at))}.` : 'La copia notturna non è ancora partita.'} Serve pg_cron: si attiva eseguendo promemoria.sql e poi di nuovo schema.sql (è nella guida).</div></div>` : ''}
        <div class="row" style="margin:10px 0"><button type="button" class="btn" data-a="now">${icon('refresh')}Copia adesso</button><button type="button" class="btn primary" data-a="full">${icon('download')}Copia sul PC o su Drive</button></div>
        <p class="hint">${pf.lastLabCopy ? `Ultima copia salvata fuori dal server ${esc(ago(pf.lastLabCopy))}.` : 'Non hai ancora salvato una copia fuori dal server.'}</p>
        ${copySettingsHtml('labCopyEvery', 'Ricordami di salvarne una fuori dal server')}
        <div class="section-title">Sul server <span class="count">${list.length}</span></div>
        ${list.length ? `<div class="card menu">${list.map((b) => `<button type="button" class="menu-row" data-b="${b.id}">${icon(b.kind === 'auto' ? 'clock' : 'user')}<div class="grow"><div>${esc(new Date(b.made_at).toLocaleString('it-IT', { weekday: 'short', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' }))}</div>
          <div class="sub">${b.kind === 'auto' ? 'notturna' : `fatta da ${esc(person(b.made_by) ? firstName(b.made_by) : 'un amministratore')}`} · ${esc(fmtBytes(b.bytes || 0))} · ${b.counts?.items ?? 0} articoli, ${b.counts?.strains ?? 0} ceppi, ${b.counts?.lab_journal ?? 0} pagine</div></div>${icon('chev', 'chev')}</button>`).join('')}</div>` : '<p class="hint">Ancora nessuna copia.</p>'}`;
    };
    load();
    sh.addEventListener('click', (e) => {
      const b = e.target.closest('[data-b]'); if (b) { backupSheet(Number(b.dataset.b)); return; }
      const a = e.target.closest('[data-a]')?.dataset.a;
      if (a === 'now') busy(e.target.closest('button'), async () => { try { await S.api.makeBackup(); toast('Copia fatta'); load(); } catch (x) { toast(x.message); } });
      if (a === 'full') labCopySheet();
    });
  });
}

function backupSheet(id) {
  openSheet('Copia di sicurezza', `<div class="card menu">
      <button type="button" class="menu-row" data-a="xlsx">${icon('sheet')}<div class="grow"><div>Scarica in Excel</div><div class="sub">un foglio per tabella, da leggere</div></div>${icon('chev', 'chev')}</button>
      <button type="button" class="menu-row" data-a="json">${icon('file')}<div class="grow"><div>Scarica il file completo</div><div class="sub">.json, serve per ripristinare</div></div>${icon('chev', 'chev')}</button>
      <button type="button" class="menu-row" data-a="miss">${icon('history')}<div class="grow"><div>Recupera cose cancellate</div><div class="sub">quello che c'era in questa copia e adesso non c'è più</div></div>${icon('chev', 'chev')}</button></div>
    <div id="miss"></div>
    <button type="button" class="btn ghost block danger-text" data-a="del" style="margin-top:12px">${icon('trash')}Elimina questa copia</button>`, (sh) => {
    sh.addEventListener('click', (e) => {
      const a = e.target.closest('[data-a]')?.dataset.a; if (!a) return;
      const btn = e.target.closest('button');
      if (a === 'xlsx' || a === 'json') busy(btn, async () => {
        try {
          const data = await S.api.backupData(id);
          if (a === 'json') await saveBlob(new Blob([JSON.stringify({ app: 'labapp', backup: id, tables: data }, null, 1)], { type: 'application/json' }), `LabApp copia ${id} ${todayKey()}.json`);
          else await saveBlob(backupXlsx(data), `LabApp copia ${id} ${todayKey()}.xlsx`);
        } catch (x) { toast(x.message); }
      });
      if (a === 'miss') busy(btn, async () => {
        try {
          const rows = await S.api.backupMissing(id);
          const by = new Map(); for (const r of rows) { if (!by.has(r.tbl)) by.set(r.tbl, []); by.get(r.tbl).push(r); }
          $('#miss', sh).innerHTML = rows.length ? `<form id="rf"><p class="hint">Scegli cosa rimettere. Torna com'era nella copia, con quello che dipendeva da lui (storia, codici, versioni). Le foto cancellate non tornano.</p>
            ${[...by.entries()].map(([t, rs]) => `<div class="section-title">${esc(TABLE_LABEL[t] || t)} <span class="count">${rs.length}</span></div><div class="card">${rs.slice(0, 200).map((r) => `<label class="toggle-row"><div class="grow">${esc(r.label)}<div class="sub">${esc([r.day && fmtDate(r.day.slice(0, 10)), r.owner && person(r.owner)?.full_name].filter(Boolean).join(' · '))}</div></div><input type="checkbox" data-t="${esc(t)}" value="${esc(r.id)}"></label>`).join('')}</div>`).join('')}
            <button class="btn primary block" type="submit" style="margin-top:10px">${icon('refresh')}Rimetti quelli scelti</button></form>` : '<p class="hint">Niente da recuperare: tutto quello che c\'era in questa copia c\'è ancora.</p>';
          $('#rf', sh)?.addEventListener('submit', (ev) => {
            ev.preventDefault();
            const pick = new Map(); for (const c of ev.target.querySelectorAll('input:checked')) { if (!pick.has(c.dataset.t)) pick.set(c.dataset.t, []); pick.get(c.dataset.t).push(c.value); }
            if (!pick.size) { toast('Scegli almeno una voce'); return; }
            busy(ev.submitter, async () => {
              try { let n = 0; for (const [t, ids] of pick) n += await S.api.restoreRows(id, t, ids); await loadData(true); toast(n ? (n === 1 ? 'Rimessa 1 voce' : `Rimesse ${n} voci`) : 'Niente da rimettere'); closeSheet(); render(); } catch (x) { toast(x.message); }
            });
          });
        } catch (x) { toast(x.message); }
      });
      if (a === 'del') confirmSheet('Eliminare la copia?', 'Le altre restano.', 'Elimina', true, async () => { try { await S.api.deleteBackup(id); toast('Copia eliminata'); openBackups(); } catch (x) { toast(x.message); } });
    });
  });
}
function backupXlsx(data) {
  const sheets = [];
  for (const [t, rows] of Object.entries(data || {})) {
    if (!Array.isArray(rows) || !rows.length) continue;
    const cols = [...new Set(rows.flatMap((r) => Object.keys(r)))];
    sheets.push({ name: (TABLE_LABEL[t] || t).slice(0, 31), rows: [cols, ...rows.map((r) => cols.map((c) => { const v = r[c]; return v == null ? '' : typeof v === 'object' ? JSON.stringify(v) : typeof v === 'boolean' ? (v ? 'sì' : 'no') : v; }))] });
  }
  return xlsxBlob(sheets.length ? sheets : [{ name: 'Vuota', rows: [['Nessun dato']] }]);
}
function labCopySheet() {
  openSheet('Copia completa', `<p class="hint" style="margin-top:0">Un file .zip con tutti i dati del laboratorio (anche in Excel) e, se vuoi, tutte le foto. Salvalo sul PC, su una chiavetta o su Drive: sul telefono tocca Condividi e scegli Drive o File.</p>
    <label class="toggle-row"><div class="grow">Con le foto<div class="sub" id="phn">conto le foto…</div></div><input type="checkbox" id="wph" checked></label>
    <p class="hint" id="st"></p>
    <div class="row"><button type="button" class="btn primary" data-mode="save">${icon('download')}Scarica</button>${canShareFiles() ? `<button type="button" class="btn" data-mode="share">${icon('share')}Condividi</button>` : ''}</div>`, (sh) => {
    let paths = null;
    S.api.listPhotos().then((p) => { paths = p; $('#phn', sh).textContent = `${p.length} foto, ${p.length > 200 ? 'qualche minuto' : 'poco tempo'}`; }).catch(() => { $('#phn', sh).textContent = 'non riesco a contarle'; });
    sh.addEventListener('click', (e) => {
      const b = e.target.closest('[data-mode]'); if (!b) return;
      busy(b, async () => {
        const say = (t) => { $('#st', sh).textContent = t; };
        try {
          say('Faccio una copia fresca sul server…');
          const id = await S.api.makeBackup();
          const data = await S.api.backupData(id);
          const files = [{ name: 'dati.json', data: JSON.stringify({ app: 'labapp', made_at: new Date().toISOString(), tables: data }, null, 1) }];
          say('Preparo l\'Excel…');
          files.push({ name: 'tabelle.xlsx', data: new Uint8Array(await backupXlsx(data).arrayBuffer()) });
          if ($('#wph', sh).checked) {
            const ps = paths || await S.api.listPhotos();
            let k = 0;
            for (const p of ps) {
              say(`Scarico le foto, ${++k} di ${ps.length}…`);
              try { files.push({ name: `foto/${p}`, data: new Uint8Array(await (await S.api.photoBlob(p)).arrayBuffer()) }); } catch { /* foto non raggiungibile */ }
            }
          }
          files.push({ name: 'LEGGIMI.txt', data: `Copia di ${BRAND.name}, ${new Date().toLocaleString('it-IT')}.\r\ndati.json contiene tutte le tabelle del database, tabelle.xlsx le stesse da leggere, foto/ le foto con lo stesso percorso dell'app.\r\nPer ripristinare serve l'amministratore: la copia si carica nel database con lo stesso schema.sql.\r\n` });
          say('Comprimo…');
          const ok = await shareOrSave(zipStore(files), `LabApp copia ${todayKey()}.zip`, b.dataset.mode);
          if (ok) { savePrefs({ lastLabCopy: new Date().toISOString() }); closeSheet(); toast('Copia salvata'); }
        } catch (x) { say(''); toast(x.message); }
      });
    });
  });
}

// ===========================================================================
//  Accesso e attesa di approvazione
